from __future__ import absolute_import

import time
from taf.ul.oam.selenium_rap_manager.common import TabBar, LocalBasicPage
from taf.ul.oam.selenium_rap_manager.exceptions import NetworkCannotBeConfigured
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException


class Network(LocalBasicPage):
    _NETWORK_PANEL_BODY = '/html/body/div[2]/div/div[2]/div[1]/div[1]/div[2]'
    __IP_ADDRESS = _NETWORK_PANEL_BODY + '/div[2]/div/div[2]/div/div[3]/div/div/input'
    _PREFIX_LENGTH = _NETWORK_PANEL_BODY + '/div[2]/div/div[2]/div/div[4]/div/div/input'
    _VLAN_ID = _NETWORK_PANEL_BODY + '/div[2]/div/div[3]/div/div[3]/div/div/input'
    _SEND_SETTING_BUTTON = _NETWORK_PANEL_BODY + '/div[4]/div/button'
    _STATIC_ROUTES_TABLE_THEAD = '//h4[contains(text(), "IPv4/IPv6 static routes")]/../..//table[contains(@class,"header-table")]'
    _STATIC_ROUTES_TABLE_TBODY = '//h4[contains(text(), "IPv4/IPv6 static routes")]/../..//table[contains(@class,"body-table")]'
    _STATIC_ROUTES_ADD_BTN = _NETWORK_PANEL_BODY + '/div[3]/div[2]//table/thead/tr/th[5]'
    _CONFIRM_MODAL = '//div[contains(@class, "n-dialog-confirm")]'

    def __init__(self, driver):
        super(Network, self).__init__(driver)
        self._tab_bar = TabBar(driver)
        self._tab_bar.click_network()

    def configure_network(self, ip_address, prefix_length, vlan_id, static_routes_update_list,
                          static_routes_delete_list, static_routes_add_list):
        try:
            self.wait_for_enable((By.XPATH, self.__IP_ADDRESS))
        except TimeoutException:
            raise NetworkCannotBeConfigured('Network page can not be configured')

        time.sleep(3)

        self.insert_text_to_enable_element((By.XPATH, self.__IP_ADDRESS), ip_address, use_ctrl_a=True)

        self.insert_text_to_enable_element((By.XPATH, self._PREFIX_LENGTH), prefix_length, use_ctrl_a=True)

        if vlan_id is not None:
            self.insert_text_to_enable_element((By.XPATH, self._VLAN_ID), vlan_id, use_ctrl_a=True)

        if len(static_routes_update_list) > 0:
            self._update_static_routes(static_routes_update_list)

        if len(static_routes_delete_list) > 0:
            self._delete_static_routes(static_routes_delete_list)

        if len(static_routes_add_list) > 0:
            self._add_static_routes(static_routes_add_list)

        self._submit_network_configuration()

        send_result_xpath = self._SEND_SETTING_BUTTON + '/../span'
        result = self.get_text_by_xpath_until_element_visible(send_result_xpath)
        return result

    def _submit_network_configuration(self):
        self.click_enabled_element((By.XPATH, self._SEND_SETTING_BUTTON))
        self.wait_for_visibility((By.XPATH, self._CONFIRM_MODAL), 15)
        send_btn_xpath = self._CONFIRM_MODAL + '//button[text()="Send"]'
        self.click_enabled_element((By.XPATH, send_btn_xpath))

    def _update_static_routes(self, update_list):
        for index, item in enumerate(update_list):
            row_index = item['index']
            edit_xpath = self._STATIC_ROUTES_TABLE_TBODY + '//tr[{}]/td[1]/div'.format(row_index)
            edit_element = self._driver.find_element_by_xpath(edit_xpath)
            ip_xpath = self._STATIC_ROUTES_TABLE_TBODY + '//tr[{}]/td[2]/input'.format(row_index)
            prefix_xpath = self._STATIC_ROUTES_TABLE_TBODY + '//tr[{}]/td[3]/input'.format(row_index)
            gate_way_xpath = self._STATIC_ROUTES_TABLE_TBODY + '//tr[{}]/td[4]/input'.format(row_index)

            if 'icon-edit' in edit_element.get_attribute('class'):
                self.click_enabled_element((By.XPATH, edit_xpath))

            self._insert_values_in_static_routes(item, ip_xpath, prefix_xpath, gate_way_xpath)
            self.click_enabled_element((By.XPATH, edit_xpath))

    def _delete_static_routes(self, delete_list):
        for index, item in enumerate(delete_list):
            [ip, prefix, gate_way] = item['identify'].split(":")
            delete_xpath = self._STATIC_ROUTES_TABLE_TBODY + \
                '//td[2][contains(text(),"{ip}")]/..//td[3][contains(text(),"{prefix}")]' \
                '/..//td[4][contains(text(),"{gate_way}")]/../td[5]' \
                .format(ip=ip, prefix=prefix, gate_way=gate_way)
            self.click_element_by_xpath(delete_xpath)

    def _insert_values_in_static_routes(self, configuration, ip_xpath, prefix_xpath, gate_way_xpath):
        xpath_list = {'ip': ip_xpath, 'prefix': prefix_xpath, 'gate_way': gate_way_xpath}

        for name in xpath_list.keys():
            if hasattr(configuration, name):
                self.click_enabled_element((By.XPATH, xpath_list[name]))
                self.insert_text_to_enable_element((By.XPATH, xpath_list[name]), configuration[name], use_ctrl_a=True)

    def _add_static_routes(self, add_list):
        for index, item in enumerate(add_list):
            last_row_xpath = self._STATIC_ROUTES_TABLE_TBODY + '//tr[last()]'
            ip_xpath = last_row_xpath + '/td[2]/input'
            prefix_xpath = last_row_xpath + '/td[3]/input'
            gate_way_xpath = last_row_xpath + '/td[4]/input'

            self.click_enabled_element((By.XPATH, self._STATIC_ROUTES_ADD_BTN))

            self._insert_values_in_static_routes(item, ip_xpath, prefix_xpath, gate_way_xpath)

            edit_xpath = last_row_xpath + '/td[1]/div'
            self.click_enabled_element((By.XPATH, edit_xpath))
